  default = "us-east-1"
}

# Explicit AZ list to avoid provider data lookups requiring ec2:DescribeAvailabilityZones
variable "azs" {
  type = list(string)
  default = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

locals {
  default_tags = {
    Owner       = "iac-eval"
    Environment = "dev"
