  subnet_ids = [aws_subnet.primary_a.id, aws_subnet.primary_b.id]
  tags       = local.default_tags
}

resource "aws_kms_key" "primary" {
  description = "KMS key for Redshift primary cluster (us-east-1)"
  deletion_window_in_days = 30
  tags       = local.default_tags
}

