  type = list(string)
  default = ["us-east-1a", "us-east-1b"]
}

# VPC CIDR
variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

# AMI ID is provided as a variable to avoid data lookups requiring ec2:DescribeImages.
# Default is a known Amazon Linux 2 AMI for us-east-1 (adjust if using another region).
variable "ami" {
