}

# Two subnets (user-specified AZs) for Gateway Load Balancer subnets
resource "aws_subnet" "gwlb_public_a" {
  vpc_id                  = aws_vpc.gwlb_vpc.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 0)
